package dev.zomboid.clans;
import java.nio.file.*;import java.io.*;import java.util.*;
public final class ClanConfig {
 public static final ClanConfig INSTANCE=new ClanConfig(Path.of("config/factionfriction-zomboid-clans.properties"));
 public final int prepTicks,durationTicks,pairCooldownTicks,killCooldownTicks,maxVictimKills,killPoints,capturePoints,defensePoints,maxRewardBundles;
 public final Map<String,Integer> bundle;
 public ClanConfig(Path path){Properties p=new Properties();p.setProperty("preparationMinutes","5");p.setProperty("warMinutes","60");p.setProperty("pairCooldownMinutes","30");p.setProperty("sameVictimCooldownSeconds","120");p.setProperty("maxScoredKillsPerVictim","3");p.setProperty("killPoints","5");p.setProperty("capturePoints","20");p.setProperty("defensePoints","10");p.setProperty("maxRewardBundles","8");p.setProperty("rewardItems","minecraft:cooked_beef=4,minecraft:honey_bottle=1,minecraft:iron_ingot=3,minecraft:arrow=8,minecraft:leather=2,minecraft:torch=8,minecraft:iron_axe=1,minecraft:leather_chestplate=1");
  try{if(Files.exists(path)){try(InputStream in=Files.newInputStream(path)){p.load(in);}}else{Files.createDirectories(path.getParent());try(OutputStream out=Files.newOutputStream(path)){p.store(out,"Zomboid Clans: server rules. Restart server after edits. Timers use world ticks (pause when server stops). Reward IDs may name installed mod items; plain stacks only, no ammo/gun components generated.");}}}catch(IOException e){throw new IllegalStateException("Could not read/write clan rules",e);}
  prepTicks=integer(p,"preparationMinutes",5,1,120)*1200;durationTicks=integer(p,"warMinutes",60,5,1440)*1200;pairCooldownTicks=integer(p,"pairCooldownMinutes",30,1,1440)*1200;killCooldownTicks=integer(p,"sameVictimCooldownSeconds",120,10,3600)*20;maxVictimKills=integer(p,"maxScoredKillsPerVictim",3,1,10);killPoints=integer(p,"killPoints",5,1,100);capturePoints=integer(p,"capturePoints",20,1,100);defensePoints=integer(p,"defensePoints",10,1,100);maxRewardBundles=integer(p,"maxRewardBundles",8,1,32);bundle=parseItems(p.getProperty("rewardItems"));
 }
 private static int integer(Properties p,String k,int d,int lo,int hi){try{return Math.max(lo,Math.min(hi,Integer.parseInt(p.getProperty(k))));}catch(Exception e){return d;}}
 public static Map<String,Integer> parseItems(String text){Map<String,Integer> out=new LinkedHashMap<>();for(String entry:text.split(",")){String[] a=entry.trim().split("=");if(a.length!=2||!a[0].matches("[a-z0-9_.-]+:[a-z0-9_./-]+"))throw new IllegalArgumentException("Invalid reward: "+entry);int count=Integer.parseInt(a[1]);if(count<1||count>64||out.size()>=32)throw new IllegalArgumentException("Reward outside limits: "+entry);out.put(a[0],count);}if(out.isEmpty())throw new IllegalArgumentException("Empty reward pool");return Collections.unmodifiableMap(out);}
}
